#!/usr/bin/env python3
"""Build the static research site from the committed, public results snapshot."""
import hashlib
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / "site"
DATA = json.loads((SITE / "data/results.json").read_text())
F = DATA["fsc"]
C = DATA["comparison"]
FINAL = next(a for a in F["arms"] if a["id"] == "final")
escape = html.escape


def number(x, digits=2):
    return f"{x:.{digits}f}"


def table(headers, rows, caption):
    return '<div class="table-scroll" tabindex="0" role="region" aria-label="' + escape(caption) + '"><table><caption>' + escape(caption) + '</caption><thead><tr>' + ''.join('<th scope="col">' + escape(h) + '</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<th scope="row">' + str(v) + '</th>' if i == 0 else '<td>' + str(v) + '</td>' for i, v in enumerate(row)) + '</tr>' for row in rows) + '</tbody></table></div>'


def page(title, body, active="home"):
    payload = json.dumps(DATA, separators=(",", ":")).replace("<", "\\u003c")
    mark = '<svg class="mark" viewBox="0 0 48 44" aria-hidden="true"><rect class="mark-top" x="13" y="4" width="22" height="10" rx="5"/><rect class="mark-mid" x="8" y="17" width="32" height="10" rx="5"/><rect class="mark-base" x="3" y="30" width="42" height="10" rx="5"/></svg>'
    return f'''<!doctype html>
<html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark"><meta name="description" content="SapinSapin speech experiments: training results, limitations, and progress toward Filipino ASR on Mac."><title>{escape(title)} | SapinSapin Experiments</title><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/site.css"><script defer src="assets/site.js"></script></head><body>
<a class="skip" href="#main">Skip to content</a><header><div class="shell nav"><a class="brand" href="index.html">{mark}<span>SapinSapin<span class="brand-sub">Experiments</span></span></a><nav aria-label="Main navigation"><a href="index.html" {'aria-current="page"' if active == 'home' else ''}>Overview</a><a href="fsc.html" {'aria-current="page"' if active == 'fsc' else ''}>FSC study</a><a href="comparison.html" {'aria-current="page"' if active == 'comparison' else ''}>Model comparison</a><a href="release.html" {'aria-current="page"' if active == 'release' else ''}>Mac release</a></nav><button id="theme" type="button" aria-label="Switch to dark mode">Dark mode</button></div></header>
<main id="main" class="shell" tabindex="-1">{body}</main><footer><div class="shell footer"><div>{mark}<strong>SapinSapin AI</strong><p>Speech experiments by JC Diamante.<br>Results snapshot: October 3, 2026.</p></div><div><a href="https://sapinsapin.ai/">SapinSapin</a><a href="https://github.com/sapinsapin/speech-experiments">Source repository</a><a href="https://huggingface.co/zeraphim">JC on Hugging Face</a><a href="data/results.json" download>Download result data</a><a href="assets/FONT-LICENSES.txt">Font licenses</a></div></div></footer><script id="results" type="application/json">{payload}</script></body></html>'''


def heading(kicker, title, intro):
    return f'<div class="page-heading"><p class="kicker">{kicker}</p><h1>{title}</h1><p class="intro">{intro}</p></div>'


base = F["baseline"]["normalized_wer"]
wer = FINAL["overall"]["normalized_wer"]
gain = (base - wer) / base * 100
home = f'''<section class="hero"><div><p class="kicker">Philippine speech AI · research log</p><h1>Training Filipino speech models for local use.</h1><p class="intro">We train on GB10, measure what changed, and work toward transcription that runs on a Mac. Every result below has a defined dataset and scoring protocol.</p><div class="actions"><a class="button" href="fsc.html">Read the training study <span aria-hidden="true">↗</span></a><a class="text-link" href="data/results.json" download>Download the results</a></div></div><aside class="hero-result"><p class="kicker">Latest training · October 2</p><div class="score-pair"><span><b>{number(base)}<small>%</small></b><span>Base WER</span></span><span class="score-arrow" aria-hidden="true">→</span><span><b>{number(wer)}<small>%</small></b><span>After adaptation</span></span></div><p class="status caution">Learned · below-25% target missed</p><p>{number(gain)}% fewer word errors relative to the base model on the same 347-clip FSC diagnostic. This set also selected the rate and checkpoint.</p><a href="fsc.html#limits">What this result can tell us</a></aside></section>
<section class="section" id="studies"><div class="section-heading"><p class="kicker">Completed experiments</p><h2>Results, including the gaps.</h2></div><article class="study"><div class="study-index">01</div><div><p class="kicker">A17 · corrected Whisper Small training</p><h3><a href="fsc.html">The pipeline learned. Longer training did not close the gap.</a></h3><p>A three-rate LoRA sweep followed by a fresh 4,000-step run. Final WER was {number(wer)}%, compared with {number(F['arms'][0]['overall']['normalized_wer'])}% for the short reference. A transient spike recovered, but its cause remains unknown.</p><div class="study-meta"><span>4,510 training clips</span><span>9 held-out speakers</span><span>One seed</span></div></div><a class="study-link" href="fsc.html">Read Study 01 <span aria-hidden="true">↗</span></a></article>
<article class="study"><div class="study-index">02</div><div><p class="kicker">A25 · existing models, shared audio</p><h3><a href="comparison.html">Large delivered better recognition at a higher processing cost.</a></h3><p>Four existing models, 200 development recordings, and three audio conditions. Large v3 PLD normalized had the lowest WER and CER in every condition, at about four times Small’s median processing time on GB10.</p><div class="study-meta"><span>2,400 successful transcriptions</span><span>Clean, noise, dropout</span><span>Inference comparison</span></div></div><a class="study-link" href="comparison.html">Read Study 02 <span aria-hidden="true">↗</span></a></article></section>
<section class="next-section"><div><p class="kicker">Next release · in preparation</p><h2>A model for the Mac.</h2><p>Our next candidate will use reviewed data, then face matched quality checks and end-to-end Mac evaluation. The model and curated dataset are planned for JC’s Hugging Face account.</p><a class="text-link" href="release.html">See the release requirements <span aria-hidden="true">↗</span></a></div><div class="release-note"><p class="status neutral">Working name · Suman Ube 1</p><p>October 18 is the requested release target. The next training run, reviewed dataset, and Mac artifact are pending. No quality improvement or model download is claimed yet.</p></div></section>'''

rows = [["Base model", "—", "—", number(base), number(F["baseline"]["normalized_cer"]), "—"]]
for a in F["arms"]:
    rows.append(["Fresh final" if a["id"] == "final" else "Ranking " + a["learning_rate"], a["learning_rate"], str(a["selected_step"]), number(a["overall"]["normalized_wer"]), number(a["overall"]["normalized_cer"]), number(a["training_seconds"] / 60)])
arm_table = table(["Run", "Learning rate", "Selected step", "WER %", "CER %", "Training min"], rows, "Fresh-process float32 scoring on the same FSC diagnostic. Lower error is better.")
curve_rows = [[str(x["step"]), number(x["eval_normalized_wer"], 4), number(x["eval_normalized_cer"], 4), number(x["eval_loss"], 4)] for x in FINAL["curve"]]
slice_rows = [[k.capitalize(), str(v["scored"]), number(v["normalized_wer"]), number(v["normalized_cer"])] for k, v in F["slices"].items()]
recipe_rows = [["Base", '<code>' + F["base_model"] + '</code>'], ["Adaptation", "LoRA rank 32 · alpha 64 · q_proj / v_proj · dropout 0.05"], ["Batch / seed", "Effective batch 16 · seed 20260816"], ["Precision", "Float16 training · fresh float32 scoring"], ["Decoding", "Greedy, forced Tagalog transcription, length cap 83"], ["Normalization", "NFKC, lowercase, trimmed and collapsed whitespace. Punctuation retained."]]
fsc_body = heading("Study 01 · A17 · October 2, 2026", "Whisper Small learned, but missed the quality target.", f"A corrected LoRA pipeline reduced normalized WER from {number(base)}% to {number(wer)}%. The fresh 4,000-step run completed and its outputs passed local audits. The below-25% gate failed.")
fsc_body += f'''<div class="study-summary"><div><strong>{number(gain)}%</strong><span>relative reduction in word errors</span></div><div><strong>{number(FINAL['overall']['normalized_cer'])}%</strong><span>normalized character error rate</span></div><div><strong>{number(FINAL['training_seconds']/60)} min</strong><span>training, including checkpoint evaluation</span></div></div><section class="section"><h2>The corrected sweep</h2><p>All three ranking arms ran for 1,500 steps. The selected rate, 1e-3, was then trained fresh for 4,000 steps. Smaller rates performed worse within the ranking budget. This single-seed sweep does not establish a universally optimal rate.</p>{arm_table}<p class="caption">The final’s WER was 0.0758 percentage points higher than the short reference. These fresh runs had different linear-decay budgets, so this does not isolate the effect of 2,500 additional updates.</p></section>
<section class="section" id="curve"><div class="section-heading"><p class="kicker">Checkpoint evidence</p><h2>Learning, an unexplained spike, then a plateau.</h2></div><p>At step 1,200, evaluation WER rose to 99.17% and recovered to 33.72% at step 1,400. The cause was not isolated. Late checkpoints fluctuated around 31–33% WER.</p><div class="chart-panel"><div class="chart-controls"><label>Run<select id="chart-run"><option value="final">Fresh 4,000-step final</option><option value="lr1e-3">Ranking · 1e-3</option><option value="lr3e-4">Ranking · 3e-4</option><option value="lr1e-4">Ranking · 1e-4</option></select></label><label>Metric<select id="chart-metric"><option value="eval_normalized_wer">Normalized WER (%)</option><option value="eval_normalized_cer">Normalized CER (%)</option><option value="eval_loss">Evaluation loss</option></select></label></div><div id="learning-chart" aria-label="Checkpoint learning curve"></div><p id="chart-status" class="caption" aria-live="polite">Exact final-run checkpoint values appear in the table below.</p><noscript><p>JavaScript is needed for the interactive plot. All results remain available in the tables and downloadable JSON.</p></noscript></div><details><summary>Inspect all 20 final-run checkpoints</summary>{table(['Step','WER %','CER %','Evaluation loss'],curve_rows,'Trainer checkpoint evaluations. The fresh-process selected score is reported separately above.')}</details></section>
<section class="section"><h2>Performance was uneven.</h2>{table(['Speech type','Clips','WER %','CER %'],slice_rows,'Final fresh-process scores by speech type.')}<p>The worst-scoring evaluation speaker had 62.70% WER across 37 recordings. A 25-row text review found phrase substitutions and spelling disagreements, but listening and the broader A13 data audit remain pending. Text coincidences alone do not prove incorrect audio alignment.</p></section>
<section class="section two-col"><div><h2>Recipe and checks</h2>{table(['Setting','Executed value'],recipe_rows,'Frozen training recipe')}<p>Real examples verified decoder-start token handling before training. All 38 checkpoint directories retained complete resume state. All 2,776 base/adapter predictions and speaker/speech-type slices were independently recomputed locally.</p></div><aside class="note" id="limits"><p class="kicker">Limits of this result</p><h3>A diagnostic, not a sealed final test.</h3><ul><li><strong>F1:</strong> 4,510 training clips, about 3.78 hours, and 347 evaluation clips. Speaker and exact-audio overlap were zero.</li><li><strong>F2:</strong> 87 distinct normalized prompts overlapped. Evaluation selected the learning rate and checkpoint.</li><li><strong>F3:</strong> One seed was run. Fixed-seed repeatability was not bitwise identical in separate smoke tests.</li><li><strong>F4:</strong> The separate A25 final set remained unscored. No next phase or improved Mac release was completed by A17.</li></ul></aside></section>
<section class="section"><h2>What we carry into the next run</h2><ol class="learning-list"><li><b>L1 · Check the real data path.</b> Keep label-prefix assertions, save/reload checks, and pinned scoring.</li><li><b>L3 · Judge recognition, not training loss alone.</b> Low training loss did not translate into lower late-stage WER.</li><li><b>L4 · Capture anomalies deliberately.</b> Batch identities, gradient norms, and loss-scaler changes are proposed checks for a relevant repeat, not completed instrumentation.</li><li><b>L5 · Audit before choosing the intervention.</b> A13 will review at least 100 errors and roughly 500 training examples.</li></ol></section>
<section class="section"><h2>Download and provenance</h2><p>{escape(F['audit_limit'])}</p><div class="actions"><a class="button" href="data/results.json" download>Download metrics and curves</a><a class="text-link" href="data/release-manifest.json" download>Snapshot checksums</a></div><details><summary>Frozen model and data identifiers</summary><dl class="hashes"><dt>Whisper base revision</dt><dd><code>{F['model_revision']}</code></dd><dt>Training manifest SHA-256</dt><dd><code>{F['train_manifest_sha256']}</code></dd><dt>Evaluation manifest SHA-256</dt><dd><code>{F['eval_manifest_sha256']}</code></dd></dl></details><p class="caption">No dataset audio, per-example transcripts, private host details, or credentials are included in this public results snapshot.</p></section>'''

names = {"whisper-small": "Whisper Small", "small-fsc": "Small FSC", "small-pld-fil": "Small PLD Filipino", "large-v3-pld-fil-norm": "Large v3 PLD normalized"}
conditions = {"clean": "Clean", "noise10": "10 dB noise", "dropout200": "200 ms dropout"}
comp_rows = [[names[r["model_key"]], conditions[r["condition"]], number(r["normalized_wer_percent"]), number(r["normalized_cer_percent"]), number(r["median_latency_s"] * 1000, 0), number(r["cuda_peak_allocated_bytes"] / 1024**3)] for r in C["results"]]
comparison_body = heading("Study 02 · A25 · October 2, 2026", "Four models. The same development recordings.", "Large v3 PLD normalized had the lowest word and character error rates in every tested condition. Its median processing time was about four times Whisper Small’s on GB10.")
comparison_body += f'''<section class="section"><h2>Quality and processing cost</h2><p>All 2,400 transcription attempts succeeded: four existing models × 200 recordings × three conditions. This is an inference comparison, not four new training runs.</p>{table(['Model','Condition','WER %','CER %','Median ms','CUDA GiB'],comp_rows,'Primary normalized scores and measured median processing time. Lower is better. CUDA figures are peak allocated memory.')}<p class="caption">The public Small FSC model is an existing SapinSapin checkpoint. It is not our unpublished A17 adapter.</p></section>
<section class="section two-col"><div><h2>Matched protocol</h2><p>The same pinned FLEURS Filipino development audio was scored under clean audio, seeded white noise at 10 dB SNR, and a seeded 200 ms dropout. Greedy Tagalog decoding used 30-second chunks and a 448-token cap.</p><p>Primary normalization lowercased and collapsed whitespace after NFKC. Punctuation and accents remained in the score. All 12 case scores passed local independent recomputation.</p><h3>Recommendation within this benchmark</h3><p>Use Large as the quality reference and Small as the compact baseline. Small PLD improved clean and dropout WER, but had worse CER in every condition and worse noisy WER than unadapted Small.</p></div><aside class="note"><p class="kicker">Interpretation limits</p><h3>These scores are not A17’s FSC scores.</h3><p>The corpus and decoding limits differ. This inspected development set cannot establish a final unseen-test result. The separate 200-recording final reservation remains unscored.</p><p>{escape(C['timing'])} TTS process presence was observed; request-level service health was not measured. CUDA memory and RSS overlap on GB10 and must not be added.</p></aside></section><section class="section"><h2>Reuse the results</h2><p>Published model-card scores use other protocols. This table ranks only the four models under this shared development benchmark.</p><div class="actions"><a class="button" href="data/results.json" download>Download comparison data</a><a class="text-link" href="https://huggingface.co/sapinsapin">Browse SapinSapin models</a></div></section>'''

release_body = heading("Mac release · planned", "Suman Ube 1 is a working name. The results will decide the release.", "The intended contribution is a compact Filipino recognizer with a verified end-to-end Mac path. October 18 is the requested target date. The next candidate has not been trained or evaluated yet.")
release_body += '''<section class="section"><h2>What must be delivered</h2><div class="release-row"><span class="status neutral">D1 · Model pending</span><div><h3>Independently trained weights and a usable Mac artifact</h3><p>Reviewed-data training, a pinned model card, fresh reload checks, matched baseline/candidate scores, and a verified Mac runner. Record load time, processing time, memory, artifact size, and any conversion loss in recognition quality.</p><p>Proposed personal repository: <code>zeraphim/suman-ube-1</code>. The final name remains provisional under SapinSapin’s draft naming proposal. Suman applies to the verified edge release. No instruction-tuning or distillation is claimed.</p></div></div><div class="release-row"><span class="status neutral">D2 · Dataset pending</span><div><h3>A reviewed FSC-derived dataset release</h3><p>A13’s reviewed examples, corrections or exclusion reasons, source revision and recording IDs, audio hashes, and reproducible split/filter rules. Attribute the original Filipino Speech Corpus and distinguish our curation from newly collected recordings.</p><p>Proposed personal repository: <code>zeraphim/fsc-reviewed-1</code>. Publish eligible audio only after source terms are checked. A manifest-and-annotation release is the fallback if audio redistribution is unresolved. Final evaluation data stays separate from training and tuning.</p></div></div><div class="release-row"><span class="status">D3 · Results site available</span><div><h3>A public experiment record</h3><p>This site currently presents A17 training and A25 inference evidence. It will add the candidate’s actual results, regressions, methods, Mac measurements, and verified Hub links when those artifacts exist.</p></div></div></section><section class="section two-col"><div><h2>The next executable step is A13.</h2><p>Listen to at least 100 transcription errors and review roughly 500 existing training examples. Then choose one intervention from the observed failure categories. Do not change the frozen diagnostic membership or scoring to lower the number.</p><p>The original FSC milestone remains below 25% normalized WER with credible learning. A separate final evaluation must support any generalization claim. Neither score is guaranteed by the release date.</p><a class="text-link" href="https://huggingface.co/zeraphim">View JC’s Hugging Face profile ↗</a></div><aside class="note"><p class="kicker">What is verified today</p><h3>Infrastructure and earlier evidence.</h3><p>The GB10 training harness, smoke recovery, A17 checkpoints and scoring, and the existing-model comparison are verified. Previous M5 conversion checks used an existing public Small FSC checkpoint. They do not establish compatibility, quality, or speed for the next candidate.</p><p>No new candidate weights or reviewed dataset are downloadable from this page yet.</p></aside></section>'''

for filename, title, body, active in [("index.html", "Speech experiments", home, "home"), ("fsc.html", "Corrected FSC training", fsc_body, "fsc"), ("comparison.html", "Four-model comparison", comparison_body, "comparison"), ("release.html", "Mac model release", release_body, "release")]:
    (SITE / filename).write_text(page(title, body, active))
manifest = {"snapshot_date": DATA["updated"], "files": [{"path": str(p.relative_to(SITE)), "sha256": hashlib.sha256(p.read_bytes()).hexdigest(), "bytes": p.stat().st_size} for p in sorted(SITE.rglob("*")) if p.is_file() and p.name != "release-manifest.json"]}
(SITE / "data/release-manifest.json").write_text(json.dumps(manifest, indent=2) + "\n")
print(f"Built 4 pages and {len(manifest['files'])} checksummed files.")
